package com.noop.analytics

import com.noop.data.DailyMetric
import org.junit.Assert.*
import org.junit.Test

class SleepRecalculationDependentsTest {
    private fun rows(hrv: Double) = (0 until 31).map { i ->
        DailyMetric("my-whoop-noop", "2026-07-%02d".format(java.util.Locale.ROOT, i + 1),
            totalSleepMin = 420.0, efficiency = 0.9, deepMin = 90.0, remMin = 100.0, lightMin = 230.0,
            disturbances = 1, restingHr = 48 + i % 5, avgHrv = if (i == 19) hrv else (45 + (i % 7) * 3).toDouble(),
            recovery = -1.0, strain = 10.0, exerciseCount = 0, respRateBpm = 15.0 + (i % 4) * 0.2, skinTempC = 33.0 + (i % 3) * 0.1)
    }
    private fun updates(hrv: Double, refresh: Boolean, selected: String = "2026-07-20") =
        SleepRecalculationDependents.updates(selected, "2026-07-31", refresh, emptyList(), rows(hrv), emptyMap(), "my-whoop", 0.0, 0.0)

    @Test fun onlyCurrentBaselineWindowCanChange() {
        assertEquals((11..31).map { "2026-07-%02d".format(java.util.Locale.ROOT, it) }, updates(80.0, true).map { it.day })
        assertTrue(updates(80.0, true, "2026-07-01").isEmpty())
        assertTrue(updates(80.0, true, "2026-08-01").isEmpty())
        assertEquals(listOf("2026-07-20"), updates(80.0, false).map { it.day })
    }

